import * as T from './three.module.js';import {batchRigidDetails} from './rigid-details.js';
export function buildShowGarden(scene){const root=new T.Group();scene.add(root);const mats=new Map(),mat=c=>{if(!mats.has(c))mats.set(c,new T.MeshStandardMaterial({color:c,roughness:.86}));return mats.get(c);};function box(w,h,d,c,x,y,z){const o=new T.Mesh(new T.BoxGeometry(w,h,d),mat(c));o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;root.add(o);return o;}
 // Original pavilion, deep window recesses, stone terrace, railings and planted borders.
 box(22,.20,9,'#c9b896',0,0,-8);box(18,5.5,4,'#decab0',0,2.8,-12);box(19,.25,4.8,'#eadcc2',0,5.6,-12);box(18,.18,4.4,'#b8a687',0,3.9,-9.8);for(let i=0;i<7;i++){const x=(i-3)*2.4;box(.20,4.2,.22,'#efe3ce',x,2.1,-9.5);box(1.25,2.25,.08,'#365964',x,2.65,-9.96);box(1.40,.12,.13,'#d5c0a0',x,1.48,-9.82);box(.07,2.25,.15,'#eee1ca',x,2.65,-9.78);box(1.35,.075,.15,'#eee1ca',x,2.6,-9.78);}
 for(const side of [-1,1]){for(let i=0;i<16;i++){const x=side*(4.2+i*.44);box(.09,.85,.09,'#ded7bd',x,.7,-4.1);}box(7,.10,.13,'#eee2c5',side*7.2,1.14,-4.1);box(7,.10,.13,'#eee2c5',side*7.2,.32,-4.1);}
 for(let i=0;i<3;i++)box(4.2,.16,1.1,'#d4c3a3',0,.20-i*.12,-3.7+i*.9);
 const dummy=new T.Object3D(),leafMat=new T.MeshStandardMaterial({color:'#416247',roughness:1}),hedges=new T.InstancedMesh(new T.SphereGeometry(1,12,8),leafMat,54);for(let i=0;i<54;i++){const side=i<27?-1:1,j=i%27;dummy.position.set(side*(3.5+(j%9)*.8),.45,-4.6-Math.floor(j/9)*.6);dummy.scale.set(.60,.62,.52);dummy.updateMatrix();hedges.setMatrixAt(i,dummy.matrix);}hedges.castShadow=hedges.receiveShadow=true;root.add(hedges);
 const flowers=new T.InstancedMesh(new T.SphereGeometry(1,8,6),new T.MeshStandardMaterial({color:'#ecc767',roughness:.82}),180),centers=new T.InstancedMesh(new T.SphereGeometry(1,6,4),mat('#826237'),36);for(let i=0;i<180;i++){const j=Math.floor(i/5),petal=i%5,side=j<18?-1:1,t=j%18,x=side*(3.7+(t%9)*.80),z=-3.8-Math.floor(t/9)*.7,a=petal*Math.PI*2/5;dummy.position.set(x+Math.sin(a)*.12,.62+Math.cos(a)*.1,z);dummy.scale.set(.10,.09,.065);dummy.updateMatrix();flowers.setMatrixAt(i,dummy.matrix);if(!petal){dummy.position.set(x,.62,z+.03);dummy.scale.set(.065,.065,.045);dummy.updateMatrix();centers.setMatrixAt(j,dummy.matrix);}}root.add(flowers,centers);
 const blades=new T.InstancedMesh(new T.ConeGeometry(.018,.20,3),new T.MeshStandardMaterial({color:'#799252',roughness:1}),800);for(let i=0;i<800;i++){const x=Math.sin(i*127.1)*16,z=Math.cos(i*311.7)*12;if(Math.abs(x)<2.4&&Math.abs(z)<3.5){dummy.scale.setScalar(0);}else dummy.scale.set(1,.6+((i*37)%10)/10,1);dummy.position.set(x,.10,z);dummy.rotation.set(0,i*2.4,Math.sin(i)*.12);dummy.updateMatrix();blades.setMatrixAt(i,dummy.matrix);}root.add(blades);for(const o of [hedges,flowers,centers,blades])o.computeBoundingSphere();batchRigidDetails(root);return root;}
